/bin/zsh -lc "python -c 'import pandas as pd,numpy as np; from scipy.optimize import minimize; from scipy.special import expit; D=pd.read_csv(\"data/nls_ses_processed.csv\"); y=D[\"BA DEGREE COMPLETED\"].to_numpy(float); x=np.c_[np.ones(len(y)),D.SES.to_numpy(float)]; f=lambda b:(lambda e,p:(np.logaddexp(0,e).sum()-y@e,x.T@(p-y),x.T@((p*(1-p))[:,None]*x)))(x@b,expit(x@b));
for m in [\"BFGS\",\"L-BFGS-B\",\"trust-exact\",\"Newton-CG\"]:
 k={\"jac\":lambda b:f(b)[1]}; k.update({\"hess\":lambda b:f(b)[2]} if m in [\"trust-exact\",\"Newton-CG\"] else {}); z=minimize(lambda b:f(b)[0],np.zeros(2),method=m,options={\"gtol\":1e-10,\"maxiter\":1000},**k); print(m,z.success,z.message,z.x,f(z.x)[1],np.sqrt(np.linalg.inv(f(z.x)[2])[1,1]))'"

